#!/usr/bin/env python3
"""T-013: altars/keys.txt + altars/altars.txt -> datapack function/altar/gen/* (generated, do not edit), the Ember's lore variants, key textures.
Usage: python3 tools/gen_altars.py [altars_file [extra_keys_file]]    (default: altars/altars.txt, no extra keys; the test altar: altars/test_altars.txt altars/test_keys.txt)"""
import json, os, struct, sys, zlib
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
DP = os.path.join(ROOT, "datapack/data/last_ember"); GEN = os.path.join(DP, "function/altar/gen"); EGEN = os.path.join(DP, "function/ember/gen"); RP = os.path.join(ROOT, "resourcepack/assets/last_ember")
for d in (GEN, EGEN, os.path.join(DP, "item_modifier"), os.path.join(RP, "textures/item"), os.path.join(RP, "models/item"), os.path.join(RP, "items")): os.makedirs(d, exist_ok=True)
for d in (GEN, EGEN):
    for f in os.listdir(d):
        if f.endswith(".mcfunction"): os.remove(os.path.join(d, f))
DIMS = {"overworld": 0, "the_nether": 1, "the_end": 2}
def w(name, lines, d=GEN): open(os.path.join(d, name + ".mcfunction"), "w", encoding="utf-8").write("\n".join(lines) + "\n")
def rows(path):
    for l in open(path, encoding="utf-8"):
        l = l.split("#", 1)[0].strip()
        if l: yield l
altar_file = sys.argv[1] if len(sys.argv) > 1 else os.path.join(ROOT, "altars/altars.txt")
keys = []
for path in [os.path.join(ROOT, "altars/keys.txt")] + ([sys.argv[2]] if len(sys.argv) > 2 else []):
    for l in rows(path):
        f = l.split(None, 3); src = None if f[2] == "-" else f[2].split(",")
        keys.append(dict(id=f[0], ch=int(f[1]), src=None if src is None else dict(x=int(src[0]), y=int(src[1]), z=int(src[2]), dim=src[3] if len(src) > 3 else "overworld"), name=f[3]))
if len({k["id"] for k in keys}) != len(keys): raise SystemExit("duplicate key id")
kid = {k["id"]: k for k in keys}
altars = []
for l in rows(altar_file):
    f = l.split()
    if f[0] == "ped": altars[-1]["peds"].append(dict(x=int(f[1]), y=int(f[2]), z=int(f[3]), key=f[4]))
    else: altars.append(dict(ch=int(f[0]), id=f[1], dim=f[2], x=int(f[3]), y=int(f[4]), z=int(f[5]), peds=[]))
pid = 0
for a in altars:
    if a["dim"] not in DIMS: raise SystemExit("bad dimension " + a["dim"])
    for p in a["peds"]:
        if p["key"] not in kid: raise SystemExit("unknown key " + p["key"])
        pid += 1; p["pid"] = pid; p["aid"] = a["id"]
ROMAN = {1: "I", 2: "II", 3: "III", 4: "IV", 5: "V", 6: "VI"}
PROPS = {1: ("Свет", "Свет — светло вокруг Несущего, пока Уголь в руке."), 2: ("Тепло", "Тепло — друзья рядом с Несущим не мёрзнут."), 3: ("Зов", "Зов — Shift + ПКМ: искры укажут, куда идти дальше."),
         4: ("Взор", "Взор — тьма не касается друзей рядом с Несущим."), 5: ("Пламя", "Пламя — огонь не жжёт друзей рядом с Несущим."), 6: ("Ключ Края", "Ключ Края — нужен в конце пути.")}
BASE = "minecraft:ominous_trial_key"
# ---------------------------------------------------------------- registration
reg = ["# generated by tools/gen_altars.py: keys, altars, pedestals (idempotent, called from altar/setup)"]
for k in keys: reg.append('function last_ember:altar/key_reg {id:"%s",ch:%d,name:"%s"}' % (k["id"], k["ch"], k["name"]))
for a in altars:
    reg.append('function last_ember:altar/place {aid:"%s",ch:%d,dim:"minecraft:%s",x:%d,y:%d,z:%d,n:%d}' % (a["id"], a["ch"], a["dim"], a["x"], a["y"], a["z"], len(a["peds"])))
    for p in a["peds"]: reg.append('function last_ember:altar/ped_reg {pid:%d,aid:"%s",key:"%s"}' % (p["pid"], a["id"], p["key"]))
w("register", reg)
w("build_pending", ["# generated: registered altars whose chunk is loaded get their interactions and labels (every second)"] +
  ['execute if data storage last_ember:altars a.%s{built:0b} in minecraft:%s if loaded %d %d %d run function last_ember:altar/gen/build_%s' % (a["id"], a["dim"], a["x"], a["y"], a["z"], a["id"]) for a in altars])
for a in altars:
    b = ["# generated: the interactions and labels of the pedestals of %s (as a function run in the dimension)" % a["id"]]
    for p in a["peds"]:
        n = kid[p["key"]]["name"]
        b += ['summon minecraft:interaction %d.5 %d %d.5 {width:0.9f,height:1.4f,response:1b,Tags:["le.ped","le.ped%d"]}' % (p["x"], p["y"], p["z"], p["pid"]),
              'scoreboard players set @e[type=minecraft:interaction,tag=le.ped%d,limit=1,sort=nearest,distance=..2] le.pid %d' % (p["pid"], p["pid"]) if False else
              'execute positioned %d.5 %d %d.5 run scoreboard players set @e[type=minecraft:interaction,tag=le.ped%d,distance=..1] le.pid %d' % (p["x"], p["y"], p["z"], p["pid"], p["pid"]),
              'summon minecraft:text_display %d.5 %d.95 %d.5 {billboard:"center",text:{"text":"%s","color":"dark_gray"},background:0,see_through:0b,Tags:["le.ped_lbl","le.ped_lbl%d"],brightness:{sky:6,block:6}}' % (p["x"], p["y"] + 1, p["z"], n, p["pid"])]
    b.append('data modify storage last_ember:altars a.%s.built set value 1b' % a["id"])
    w("build_" + a["id"], b)
# ---------------------------------------------------------------- keys: give / hand
meta = ['minecraft:item_model="last_ember:key_%s"', 'minecraft:rarity="epic"', "minecraft:max_stack_size=1"]
for k in keys:
    comps = ('minecraft:custom_data={le_key:"%s",le_keep:1b,gen:$(gen)},minecraft:item_model="last_ember:key_%s",minecraft:custom_name={"text":"%s","color":"light_purple","italic":false},'
             'minecraft:lore=[{"text":"Ключ главы %s.","color":"gray","italic":false},{"text":"Место ему — на пьедестале алтаря.","color":"dark_gray","italic":false}],minecraft:rarity="epic",minecraft:max_stack_size=1') % (k["id"], k["id"], k["name"], ROMAN[k["ch"]])
    w("item_" + k["id"], ["$give @s %s[%s] 1" % (BASE, comps)]); w("hand_" + k["id"], ["$item replace entity @s weapon.mainhand with %s[%s] 1" % (BASE, comps)])
# keys_watch (every 10 ticks): one cheap pass marks new item entities (le.kchk) and the dropped keys among them (le.kitem), then one function per key.
# Each key has its own macro function (id baked in, only gen is a macro argument): a shared macro with 18 different arguments would miss the
# macro cache on every call and be re-parsed; the floor checks look only at the tagged key items (no nbt= selector over every item).
w("keys_watch", ["# generated: every 10 ticks, one call per key (uniqueness, loss, stale copies)",
                 "execute as @e[type=minecraft:item,tag=!le.kchk] if items entity @s contents %s run tag @s add le.kitem" % BASE,
                 "tag @e[type=minecraft:item,tag=!le.kchk] add le.kchk"] +
  ['function last_ember:altar/gen/kw_%s with storage last_ember:keys k.%s' % (k["id"], k["id"]) for k in keys])
for k in keys:
    i = k["id"]; m = 'minecraft:custom_data~{le_key:"%s"}' % i; v = '*[minecraft:custom_data~{le_key:"%s",gen:$(gen)}]' % i
    w("kw_" + i, ["# generated: macro gen (storage last_ember:keys k.%s): stale copies leave players and the floor; the holder is remembered; a loss is repaired" % i,
                  '$clear @a *[%s,!minecraft:custom_data~{gen:$(gen)}]' % m,
                  '$execute as @e[type=minecraft:item,tag=le.kitem] if items entity @s contents *[%s,!minecraft:custom_data~{gen:$(gen)}] run kill @s' % m,
                  'execute if data storage last_ember:keys k.%s{st:2} run return 0' % i,
                  'execute if data storage last_ember:keys k.%s{st:1} run return 0' % i,
                  'scoreboard players set #kh le.alt 0'] +
      ['$execute as @a[limit=1] if score #kh le.alt matches 0 as @a if items entity @s %s %s run function last_ember:altar/gen/kh_%s' % (sl, v, i) for sl in ("container.*", "weapon.offhand", "player.cursor", "armor.*", "enderchest.*")] +
      ['execute if score #kh le.alt matches 1 run return 0',
       '$execute as @e[type=minecraft:item,tag=le.kitem] if items entity @s contents %s run return run data modify storage last_ember:keys k.%s.it set value 1b' % (v, i),
       'execute if data storage last_ember:keys k.%s{it:1b} run function last_ember:altar/key_lost {id:"%s"}' % (i, i)])
    w("kh_" + i, ["# generated: as the holder of the valid key %s: remembered as the last one who held it" % i, "scoreboard players set #kh le.alt 1",
                  "data modify storage last_ember:keys k.%s.h set from entity @s UUID" % i, "data modify storage last_ember:keys k.%s.it set value 0b" % i,
                  "data modify storage last_ember:keys k.%s.got set value 1b" % i, "data modify storage last_ember:keys k.%s.pend set value 0b" % i])
w("keys_join", ["# generated: as a player who is online: a key that is owed to him (it was lost while he was offline)"] +
  ['execute if data storage last_ember:keys k.%s{pend:1b} run function last_ember:altar/key_owed {id:"%s"}' % (k["id"], k["id"]) for k in keys])
w("give_dispatch", ["# macro id: gives the valid copy of that key to the player"] + [])
open(os.path.join(GEN, "give_dispatch.mcfunction"), "w").write("# generated\n$function last_ember:altar/gen/item_$(id) with storage last_ember:keys k.$(id)\n")
w("hand_dispatch", ["# generated"]); open(os.path.join(GEN, "hand_dispatch.mcfunction"), "w").write("# generated\n$function last_ember:altar/gen/hand_$(id) with storage last_ember:keys k.$(id)\n")
# ---------------------------------------------------------------- altars: check, event, done
chk = ["# generated: every second: an altar with all pedestals filled starts the event when the Ember carrier is within 10 blocks, else asks for the Ember"]
for a in altars:
    n = len(a["peds"])
    chk += ['execute if score #fill_%s le.alt matches %d.. if data storage last_ember:altars a.%s{built:1b,done:0b,ev:-1} in minecraft:%s positioned %d %d %d if entity @a[tag=le.carrier,distance=..10] run function last_ember:altar/event_start {aid:"%s"}' % (a["id"], n, a["id"], a["dim"], a["x"], a["y"], a["z"], a["id"]),
            'execute if score #fill_%s le.alt matches %d.. if data storage last_ember:altars a.%s{built:1b,done:0b,ev:-1} in minecraft:%s positioned %d %d %d unless entity @a[tag=le.carrier,distance=..10] if entity @a[distance=..10] run title @a[distance=..10] actionbar {"text":"Нужен Уголь","color":"gold"}' % (a["id"], n, a["id"], a["dim"], a["x"], a["y"], a["z"])]
w("check", chk)
evloop = ["# generated: every tick, the events that run (ev >= 0)"] + ['execute if data storage last_ember:altars a.%s{ev:0} run function last_ember:altar/gen/ev_%s' % (a["id"], a["id"]) if False else
          'scoreboard players set #ev le.alt -1\nexecute store result score #ev le.alt run data get storage last_ember:altars a.%s.ev' % a["id"] + "\n" + 'execute if score #ev le.alt matches 0.. in minecraft:%s positioned %d %d %d run function last_ember:altar/gen/ev_%s' % (a["dim"], a["x"], a["y"], a["z"], a["id"]) for a in altars]
w("event_tick", evloop)
EVT = 260
for a in altars:
    L = ["# generated: one tick of the event of %s (at the altar); #ev = the tick number" % a["id"],
         "execute store result score #ev le.alt run data get storage last_ember:altars a.%s.ev" % a["id"],
         'execute store result storage last_ember:altars a.%s.ev int 1 run scoreboard players add #ev le.alt 1' % a["id"],
         "execute if score #ev le.alt matches 1 run playsound minecraft:block.beacon.activate block @a[distance=..40] ~ ~ ~ 2 0.5",
         "execute if score #ev le.alt matches 1 run title @a[distance=..40] actionbar {\"text\":\"Гул под землёй…\",\"color\":\"gray\"}",
         "execute if score #ev le.alt matches 20 run playsound minecraft:ambient.cave block @a[distance=..40] ~ ~ ~ 2 0.5",
         "execute if score #ev le.alt matches 40 run playsound minecraft:block.beacon.ambient block @a[distance=..40] ~ ~ ~ 2 0.6",
         "execute if score #ev le.alt matches 150 run playsound minecraft:entity.lightning_bolt.thunder weather @a[distance=..80] ~ ~ ~ 5 0.7",
         "execute if score #ev le.alt matches 200 run playsound minecraft:entity.lightning_bolt.thunder weather @a[distance=..80] ~ ~ ~ 6 1.0",
         "execute if score #ev le.alt matches 200 run particle minecraft:explosion_emitter ~ ~1 ~ 0 0 0 0 1 force",
         "execute if score #ev le.alt matches 200 run particle minecraft:end_rod ~ ~2 ~ 3 3 3 0.2 300 force",
         "execute if score #ev le.alt matches 200 run effect give @a[distance=..40] minecraft:night_vision 2 0 true",
         "scoreboard players operation #m le.alt = #ev le.alt", "scoreboard players operation #m le.alt %= #5 le.alt"]
    for p in a["peds"]:
        L.append("execute if score #m le.alt matches 0 positioned %d.5 %d.4 %d.5 facing entity @a[tag=le.carrier,limit=1,sort=nearest] eyes run function last_ember:altar/beam" % (p["x"], p["y"] + 1, p["z"]))
        L.append("execute if score #m le.alt matches 0 run particle minecraft:enchant %d.5 %d.4 %d.5 0.3 0.3 0.3 0.5 4" % (p["x"], p["y"] + 1, p["z"]))
    L.append("execute if score #ev le.alt matches %d.. run function last_ember:altar/gen/done_%s" % (EVT, a["id"]))
    w("ev_" + a["id"], L)
    D = ["# generated: the event of %s ends: the chapter %d is done" % (a["id"], a["ch"]),
         'data modify storage last_ember:altars a.%s.ev set value -1' % a["id"], 'data modify storage last_ember:altars a.%s.done set value 1b' % a["id"],
         "scoreboard players add #chapters le.alt 1",
         'execute in minecraft:%s as @a at @s if dimension minecraft:%s run title @s title {"text":"Глава %s завершена","color":"gold"}' % (a["dim"], a["dim"], ROMAN[a["ch"]]),
         'execute in minecraft:%s as @a at @s if dimension minecraft:%s run title @s subtitle {"text":"Уголь получил свойство: %s","color":"yellow"}' % (a["dim"], a["dim"], PROPS[a["ch"]][0]),
         "execute in minecraft:%s as @a at @s if dimension minecraft:%s run playsound minecraft:ui.toast.challenge_complete player @s ~ ~ ~ 1 1" % (a["dim"], a["dim"])]
    for p in a["peds"]: D.append('function last_ember:altar/key_done {key:"%s"}' % p["key"])
    D += ["function last_ember:altar/chapters_changed", "function last_ember:altar/hook/chapter_%d" % a["ch"]]
    w("done_" + a["id"], D)
# ---------------------------------------------------------------- admin reset by chapter
for ch in sorted({a["ch"] for a in altars}):
    R = ["# generated: the altars of the chapter %d back to the start (test): pedestals emptied, keys invalid and free, the event can run again" % ch]
    for a in altars:
        if a["ch"] != ch: continue
        R += ["data modify storage last_ember:altars a.%s.done set value 0b" % a["id"], "data modify storage last_ember:altars a.%s.ev set value -1" % a["id"], "scoreboard players set #fill_%s le.alt 0" % a["id"]]
        for p_ in a["peds"]:
            R += ["data modify storage last_ember:altars p.p%d.filled set value 0b" % p_["pid"], "kill @e[type=minecraft:item_display,tag=le.ped_item%d]" % p_["pid"],
                  "data modify entity @e[type=minecraft:text_display,tag=le.ped_lbl%d,limit=1] text.color set value \"dark_gray\"" % p_["pid"],
                  'data modify storage last_ember:keys k.%s.st set value 0' % p_["key"], 'data modify storage last_ember:keys k.%s.got set value 0b' % p_["key"], 'data modify storage last_ember:keys k.%s.it set value 0b' % p_["key"], 'data modify storage last_ember:keys k.%s.pend set value 0b' % p_["key"],
                  'function last_ember:altar/gen_bump {key:"%s"}' % p_["key"]]
    w("reset_%d" % ch, R)
# ---------------------------------------------------------------- the Call: the nearest key point not found yet, of the chapter being worked on
call = ["# generated: as the carrier: #tx le.alt #tz le.alt = the nearest source of a key of the current chapter that nobody has found yet; #found = 1 when there is one",
        "scoreboard players set #found le.alt 0", "scoreboard players set #best le.alt 2147483647",
        "execute store result score #px le.alt run data get entity @s Pos[0]", "execute store result score #pz le.alt run data get entity @s Pos[2]"]
for k in keys:
    if not k["src"]: continue
    s = k["src"]
    call += ['execute if data storage last_ember:keys k.%s{got:0b} if score #cur le.alt matches %d if dimension minecraft:%s run function last_ember:altar/gen/call_%s' % (k["id"], k["ch"], s["dim"], k["id"])]
    w("call_" + k["id"], ["scoreboard players set #dx le.alt %d" % s["x"], "scoreboard players set #dz le.alt %d" % s["z"], "scoreboard players operation #dx le.alt -= #px le.alt", "scoreboard players operation #dz le.alt -= #pz le.alt",
                          "scoreboard players operation #dx le.alt *= #dx le.alt", "scoreboard players operation #dz le.alt *= #dz le.alt", "scoreboard players operation #dx le.alt += #dz le.alt",
                          "execute if score #dx le.alt < #best le.alt run function last_ember:altar/gen/take_%s" % k["id"]])
    w("take_" + k["id"], ["scoreboard players operation #best le.alt = #dx le.alt", "scoreboard players set #tx le.alt %d" % s["x"], "scoreboard players set #tz le.alt %d" % s["z"], "scoreboard players set #found le.alt 1"])
w("call_target", call + ["# nothing to look for: the altar of the chapter"] + ['execute if score #found le.alt matches 0 if score #cur le.alt matches %d run function last_ember:altar/gen/take_altar_%s' % (a["ch"], a["id"]) for a in altars])
for a in altars: w("take_altar_" + a["id"], ["scoreboard players set #tx le.alt %d" % a["x"], "scoreboard players set #tz le.alt %d" % a["z"], "scoreboard players set #found le.alt 1"])
# ---------------------------------------------------------------- the Ember: lore by chapters
def lore(n):
    L = [{"text": "Тлеет последним жаром погасшего солнца.", "color": "gray", "italic": False}, {"text": "Передать его можно только у стелы костра.", "color": "dark_gray", "italic": False}]
    for c in range(1, n + 1): L.append({"text": PROPS[c][1], "color": "yellow", "italic": False})
    return L
for n in range(0, 7):
    json.dump({"type": "minecraft:set_lore", "mode": "replace_all", "lore": lore(n)}, open(os.path.join(DP, "item_modifier/ember_lore_%d.json" % n), "w"), ensure_ascii=False)
    comps = ('minecraft:custom_data={le_ember:1b,gen:$(gen)},minecraft:item_model="last_ember:ember",minecraft:custom_name={"text":"Последний Уголь","color":"gold","italic":false},minecraft:lore=%s,minecraft:max_stack_size=1,minecraft:rarity="epic"') % json.dumps(lore(n), ensure_ascii=False)
    w("give_%d" % n, ["$give @s minecraft:trial_key[%s] 1" % comps], EGEN)
w("relore", ["# macro n: the lore of the Ember in the carrier's inventory follows the chapters"] + ["$execute if items entity @s container.%d *[minecraft:custom_data~{le_ember:1b}] run item modify entity @s container.%d last_ember:ember_lore_$(n)" % (i, i) for i in range(36)] +
  ["$execute if items entity @s weapon.offhand *[minecraft:custom_data~{le_ember:1b}] run item modify entity @s weapon.offhand last_ember:ember_lore_$(n)"], EGEN)
w("give_dispatch", ["# as a player: the Ember of the current gen with the lore of the chapters done"] + ["execute if score #chapters le.alt matches %s run function last_ember:ember/gen/give_%d with storage last_ember:ember" % ((str(n) if n < 6 else "6.."), n) for n in range(0, 7)] + [], EGEN)
# ---------------------------------------------------------------- key textures (placeholders: a key of the colour of its chapter)
def png(path, px):
    raw = b"".join(b"\x00" + b"".join(bytes(p) for p in row) for row in px)
    def chunk(t, d): c = struct.pack(">I", len(d)) + t + d; return c + struct.pack(">I", zlib.crc32(t + d) & 0xffffffff)
    open(path, "wb").write(b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", 16, 16, 8, 6, 0, 0, 0)) + chunk(b"IDAT", zlib.compress(raw, 9)) + chunk(b"IEND", b""))
COL = {1: (120, 200, 120), 2: (90, 150, 230), 3: (230, 120, 60), 4: (190, 160, 240), 5: (200, 190, 170), 6: (240, 240, 120)}
for k in keys:
    c = COL[k["ch"]]; px = [[(0, 0, 0, 0)] * 16 for _ in range(16)]
    for y in range(2, 8):
        for x in range(2, 8):
            if (x - 4.5) ** 2 + (y - 4.5) ** 2 <= 5.5 and not (x - 4.5) ** 2 + (y - 4.5) ** 2 < 1.2: px[y][x] = (*c, 255)
    for i in range(7, 14): px[i][5] = (*c, 255); px[i][6] = (int(c[0] * 0.7), int(c[1] * 0.7), int(c[2] * 0.7), 255)
    for y in (10, 12): px[y][7] = (*c, 255); px[y][8] = (*c, 255)
    png(os.path.join(RP, "textures/item/key_%s.png" % k["id"]), px)
    open(os.path.join(RP, "models/item/key_%s.json" % k["id"]), "w").write('{ "parent": "minecraft:item/generated", "textures": { "layer0": "last_ember:item/key_%s" } }\n' % k["id"])
    open(os.path.join(RP, "items/key_%s.json" % k["id"]), "w").write('{ "model": { "type": "minecraft:model", "model": "last_ember:item/key_%s" } }\n' % k["id"])
print("altars: %d, pedestals: %d, keys: %d" % (len(altars), pid, len(keys)))
